+/** Picks a supported language from an Accept-Language header, or `fallback`. */
+export function pickLanguage(header, fallback = LANGUAGES[0]) {
+  const raw = Array.isArray(header) ? header.join(",") : header;
+  if (typeof raw !== "string" || !raw.trim()) return fallback;
+  const choices = [];
+  for (const part of raw.split(",")) {
+    const [tagPart, ...params] = part.split(";");
+    const base = tagPart.trim().toLowerCase().split("-")[0];
+    if (!LANGUAGES.includes(base)) continue;
+    let q = 1;
+    let valid = true;
+    for (const p of params) {
+      const eq = p.indexOf("=");
+      if (eq === -1) continue;
+      if (p.slice(0, eq).trim().toLowerCase() !== "q") continue;
+      const qStr = p.slice(eq + 1).trim();
+      const qNum = Number(qStr);
+      if (!/^\d+(?:\.\d+)?$/.test(qStr) || !Number.isFinite(qNum) || qNum < 0 || qNum > 1) {
+        valid = false;
+        break;
+      }
+      q = qNum;
+    }
+    if (valid && q > 0) choices.push({ lang: base, q });
+  }
+  choices.sort((a, b) => b.q - a.q);
+  return choices[0]?.lang ?? fallback;
+}
